// Type: Phase.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Phase {
    Answered,
    Preparing,
    Starting,
    Active,
    Waiting,
    Ending,
}

// Record: Phase.
impl Record for Phase {
    type Limits = Limits;
    const TAIL: Path = paths::PHASE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 42)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 42)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Answered => field::put(out, &[0], paths::PHASE_TAG),
            Self::Preparing => field::put(out, &[1], paths::PHASE_TAG),
            Self::Starting => field::put(out, &[2], paths::PHASE_TAG),
            Self::Active => field::put(out, &[3], paths::PHASE_TAG),
            Self::Waiting => field::put(out, &[4], paths::PHASE_TAG),
            Self::Ending => field::put(out, &[5], paths::PHASE_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PHASE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Answered),
            1 => Ok(Self::Preparing),
            2 => Ok(Self::Starting),
            3 => Ok(Self::Active),
            4 => Ok(Self::Waiting),
            5 => Ok(Self::Ending),
            6..=u8::MAX => Err(Problem { path: paths::PHASE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

